package com.ismartcoding.plain.lib.kgraphql.generated

import com.ismartcoding.plain.lib.kgraphql.schema.dsl.SchemaBuilder

/**
 * Expect function — the actual is generated by :kgraphql-ksp for each platform
 * target (androidMain, iosArm64Main, iosSimulatorArm64Main).
 *
 * The generated actual calls `GeneratedSchemaRegistry.registerType(...)` etc.
 * for every `@GraphQLType` / `@GraphQLInput` / `@GraphQLUnion` /
 * @GraphQLInterface` annotated class discovered at compile time.
 *
 * Using expect/actual avoids the need for `kspCommonMainMetadata` — each
 * platform's KSP run generates both the descriptor objects and the actual
 * function into the platform source set.
 */
internal expect fun registerAllGeneratedSchema()

/**
 * Expect extension — the actual is generated by :kgraphql-ksp for each platform
 * target. Scans `@GraphQLQuery` / `@GraphQLMutation` / `@GraphQLSubscription`
 * annotated functions and registers them as GraphQL operations via the standard
 * DSL, with arg names derived from the Kotlin function parameter names — no
 * need to repeat them as string literals in `resolver("a", "b") { a, b -> }`.
 */
internal expect fun SchemaBuilder.registerGeneratedResolvers()

/**
 * Expect extension — the actual is generated by :kgraphql-ksp for each platform
 * target. Same as [registerGeneratedResolvers] but for resolvers annotated with
 * `target = GraphQLSchemaTarget.PEER`, registered into the PeerGraphQL schema.
 */
internal expect fun SchemaBuilder.registerGeneratedPeerResolvers()

/**
 * Expect extension — the actual is generated by :kgraphql-ksp for each platform
 * target. Same as [registerGeneratedResolvers] but for resolvers annotated with
 * `target = GraphQLSchemaTarget.GUEST`, registered into the GuestGraphQL schema
 * (shared-file links).
 */
internal expect fun SchemaBuilder.registerGeneratedGuestResolvers()
